-- allstar_full column descriptions
ALTER TABLE `mlb_race_to_october.allstar_full`
  ALTER COLUMN playerID SET OPTIONS(description = 'Lahman\'s universal player identifier.'),
  ALTER COLUMN yearID SET OPTIONS(description = 'Season year of the All-Star Game.'),
  ALTER COLUMN game_num SET OPTIONS(description = 'Game number within the season: 1 or 2. Most years have a single ASG (game_num=1). From 1959-1962 MLB held two All-Star Games per season; those rows have game_num=2 for the second game.'),
  ALTER COLUMN gameID SET OPTIONS(description = 'Retrosheet-style identifier for the specific All-Star Game. Preserved in camelCase.'),
  ALTER COLUMN teamID SET OPTIONS(description = 'The player\'s team during the season they were selected (not the AL/NL ASG roster).'),
  ALTER COLUMN lgID SET OPTIONS(description = 'League the player represented in the ASG (\'AL\' or \'NL\').'),
  ALTER COLUMN games_played SET OPTIONS(description = '1 if the player actually appeared in the ASG, 0 or NULL if they were selected but didn\'t play (injury, manager\'s discretion, etc.). Counts of All-Star selections should NOT filter on this column; counts of All-Star appearances should.'),
  ALTER COLUMN starting_position SET OPTIONS(description = 'Position number (1-9) if the player started the game, NULL otherwise. 1=P, 2=C, 3=1B, 4=2B, 5=3B, 6=SS, 7=LF, 8=CF, 9=RF, 10=DH (DH used in some interleague-rule years).');

-- awards_players column descriptions
ALTER TABLE `mlb_race_to_october.awards_players`
  ALTER COLUMN playerID SET OPTIONS(description = 'Lahman\'s universal player identifier.'),
