  ALTER COLUMN notes SET OPTIONS(description = 'Free-text notes about the award (e.g., position for Gold Gloves like \'CF\', \'P\'; specific designation like \'pitcher\' or \'outfield\' for Silver Slugger). NULL for most awards.');

